css:
.mz *,.mz *::before,.mz *::after{box-sizing: border-box; margin: 0; padding: 0;}
.mz .recuerda{border: 2px solid var(--bosque); border-radius: 10px; padding: 5px 11px; margin-bottom: 8px;}
.mz .recuerda-titulo{font-size: 12.5px; font-weight: 700; margin-bottom: 3px; display: flex; align-items: center; gap: 6px;}
.mz .recuerda-idea{font-size: 11.5px; margin-bottom: 4px; line-height: 1.3;}
.mz .palabras-tabla{width: 100%; border-collapse: collapse; font-size: 11px;}
.mz .palabras-tabla th,.mz .palabras-tabla td{border: 1.5px solid var(--bosque); padding: 3px 6px; text-align: center;}
.mz .palabras-tabla th{background: #f3f3f3; font-family: sans-serif; font-size: 10.5px;}
.mz .palabras-tabla .signo{font-family: sans-serif; font-size: 16px; font-weight: 800;}
.mz .problemas{display: grid; grid-template-columns: 1fr; gap: 14px;}
.mz .problema{border: 1.5px solid var(--bosque); border-radius: 10px; padding: 10px 14px; display: grid; grid-template-columns: 56px 1fr; gap: 8px; align-items: start;}
.mz .problema-icono{display: flex; align-items: center; justify-content: center;}
.mz .problema-icono svg{width: 50px; height: 50px;}
.mz .problema-cuerpo{display: flex; flex-direction: column; gap: 3px;}
.mz .problema-cabecera{display: flex; align-items: baseline; gap: 5px;}
.mz .problema-num{font-family: sans-serif; font-size: 15px; font-weight: 800;}
.mz .problema-enunciado{font-size: 14px; line-height: 1.3; font-weight: 600;}
.mz .problema-resolver{display: grid; grid-template-columns: auto 1fr 1.4fr; gap: 10px; align-items: stretch; margin-top: 4px;}
.mz .signo-elegir{border: 1.5px solid var(--bosque); border-radius: 6px; padding: 4px 10px; font-family: sans-serif; font-size: 11px; font-weight: 700; display: flex; flex-direction: column; align-items: center; justify-content: center; min-width: 64px;}
.mz .signo-elegir .label{font-size: 8.5px; color: #444; letter-spacing: .4px;}
.mz .signo-elegir .opciones{font-size: 16px; font-weight: 800;}
.mz .zona{border: 1.5px dashed #555; border-radius: 6px; padding: 4px 8px; min-height: 62px;}
.mz .zona-label{font-family: sans-serif; font-size: 10px; font-weight: 700; color: #444; letter-spacing: .4px; display: block; margin-bottom: 1px;}
.mz .zona-solucion{display: flex; flex-direction: column;}
.mz .solucion-linea{flex: 1; border-bottom: 1.5px solid var(--bosque); margin-top: 6px; min-height: 32px;}
.mz .problema-enunciado,.mz .recuerda-idea{line-height: 1.875 !important;}
